import sys
from collections import defaultdict

MOD = 1000000007

def main():
    import sys
    input = sys.stdin.read().split()
    N = int(input[0])
    preferences = []
    index = 1
    for i in range(N):
        current = int(input[index])
        desired = int(input[index + 1])
        preferences.append((current, desired))
        index += 2

    current_to_desired = defaultdict(list)
    for current, desired in preferences:
        current_to_desired[current].append(desired)

    visited = [False] * (2 * N + 1)
    components = []

    def dfs(node):
        stack = [node]
        component = []
        while stack:
            node = stack.pop()
            if not visited[node]:
                visited[node] = True
                component.append(node)
                for neighbor in current_to_desired[node]:
                    if not visited[neighbor]:
                        stack.append(neighbor)
        return component

    for node in range(1, 2 * N + 1):
        if not visited[node]:
            component = dfs(node)
            components.append(component)

    result = 1
    for component in components:
        cycles = 0
        nodes_in_cycles = set()
        for node in component:
            if node not in nodes_in_cycles:
                cycle_length = 0
                current = node
                while current not in nodes_in_cycles:
                    nodes_in_cycles.add(current)
                    current = current_to_desired[current][0]
                    cycle_length += 1
                if cycle_length > 0:
                    cycles += 1
                    result = (result * cycle_length) % MOD

        if len(component) != cycles:
            result = (result * factorial(len(component) - cycles)) % MOD

    print(result)

def factorial(n):
    fact = 1
    for i in range(2, n + 1):
        fact = (fact * i) % MOD
    return fact

if __name__ == "__main__":
    main()
